*** Add File: script.js
+const form = document.querySelector("#contact-form");
+const statusMessage = document.querySelector("#form-status");
+
+const fields = [
+  {
+    input: document.querySelector("#full-name"),
+    validate(value) {
+      return value.trim() ? "" : "Enter your full name.";
+    },
+  },
+  {
+    input: document.querySelector("#email"),
+    validate(value) {
+      if (!value.trim()) {
+        return "Enter your email address.";
+      }
+
+      return this.input.validity.typeMismatch
+        ? "Enter an email address in the format name@example.com."
+        : "";
+    },
+  },
+];
+
+function removeError(input) {
+  const errorId = `${input.id}-error`;
+  const error = document.querySelector(`#${errorId}`);
+
+  input.removeAttribute("aria-invalid");
+  if (error) {
+    error.remove();
+  }
+
+  const describedBy = (input.getAttribute("aria-describedby") || "")
+    .split(" ")
+    .filter((id) => id && id !== errorId)
+    .join(" ");
+
+  if (describedBy) {
+    input.setAttribute("aria-describedby", describedBy);
+  } else {
+    input.removeAttribute("aria-describedby");
+  }
+}
+
+function showError(input, message) {
+  const errorId = `${input.id}-error`;
+  let error = document.querySelector(`#${errorId}`);
+
+  input.setAttribute("aria-invalid", "true");
+
+  if (!error) {
+    error = document.createElement("p");
+    error.id = errorId;
+    error.className = "error-message";
+    input.insertAdjacentElement("afterend", error);
+  }
+
+  error.textContent = message;
+
+  const describedBy = new Set(
+    (input.getAttribute("aria-describedby") || "").split(" ").filter(Boolean),
+  );
+  describedBy.add(errorId);
+  input.setAttribute("aria-describedby", [...describedBy].join(" "));
+}
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  let firstInvalid = null;
+  statusMessage.textContent = "";
+  statusMessage.classList.remove("has-error");
+
+  fields.forEach(({ input, validate }) => {
+    const message = validate.call({ input }, input.value);
+
+    if (message) {
+      showError(input, message);
+      firstInvalid ??= input;
+    } else {
+      removeError(input);
+    }
+  });
+
+  if (firstInvalid) {
+    statusMessage.textContent = "Please correct the highlighted fields.";
+    statusMessage.classList.add("has-error");
+    firstInvalid.focus();
+    return;
+  }
+
+  statusMessage.textContent = "Thanks. Your support request is ready to send.";
+  form.reset();
+});
+
+fields.forEach(({ input, validate }) => {
+  input.addEventListener("input", () => {
+    if (input.getAttribute("aria-invalid") !== "true") {
+      return;
+    }
+
+    const message = validate.call({ input }, input.value);
+    if (message) {
+      showError(input, message);
+    } else {
+      removeError(input);
+      statusMessage.textContent = "";
+      statusMessage.classList.remove("has-error");
+    }
+  });
+});
*** End Patch
